    if file_type is None:
        _, file_type = os.path.splitext(path)
        file_type = file_type.lstrip('.').lower()

    with open(path, 'r') as file:
        if file_type == 'json':
            import json
            return json.load(file)
        elif file_type in {'yaml', 'yml'}:
            import yaml
            return yaml.safe_load(file)
        elif file_type == 'toml':
            import tomli
            return tomli.load(file)
        elif file_type == 'pickle':
            import pickle
            return pickle.load(file)
        elif file_type in {'csv', 'tsv'}:
            import csv
            reader = csv.DictReader(file)
            return list(reader)
        else:
            raise UnsupportedFormatErr(f'Unsupported file type: {file_type}')


def json_dumps(item, default_mapping=None, force_use_builtin_json: bool=
    False, **kwargs):
    if orjson is not None and not force_use_builtin_json:
        return orjson.dumps(
            item,
            default=json_convertor_default(default_mapping),
            option=orjson.OPT_NON_STR_KEYS | orjson.OPT_SORT_KEYS,
            **kwargs
        ).decode('utf-8')
    else:
        return json.dumps(
            item,
            default=json_convertor_default(default_mapping),
            **kwargs
        )


def to_json(self, default_mapping: Optional[dict]=None,
    force_use_builtin_json=False, **kwargs):
    dic = self.to_dict(view_override=TEXT_VIEW)
    return json_dumps(
        dic,
        default_mapping=default_mapping,
        force_use_builtin_json=force_use_builtin_json,
        **kwargs,
    )


def to_dict(self, view_override=None):
